INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74472, 'spa', 'Uso adverbial o comparativo que significa ''más allá'' o ''además de lo ya dicho'', ', 'Uso adverbial o comparativo que significa ''más allá'' o ''además de lo ya dicho'', extendiendo lo que ya está a la vista. Este uso aparece una sola vez en Hechos 19:39, donde el secretario municipal dice a la asamblea amotinada que si buscan algo ''más allá de esto'', se resolverá en asamblea legítima — un uso retórico que aleja la palabra de la geografía hacia la argumentación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74473, 'spa', 'Fin, confín o extremo', 'Un fin, límite, confín o extremo: el alcance más lejano de una extensión espacial o la terminación conclusiva de un asunto. Mateo 12:42 y Lucas 11:31 emplean el plural para designar «los confines de la tierra», Romanos 10:18 lo aplica al alcance universal del evangelio, y Hebreos 6:16 lo traslada al ámbito jurídico como resolución definitiva de toda controversia mediante juramento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74475, 'spa', 'Ciudad de Panfilia', 'Todas las lenguas transliteran el nombre de la ciudad: Perge en español e inglés, Perga en francés. Abbott-Smith la identifica como «ciudad de Panfilia». Las tres apariciones se hallan en Hechos: la llegada de Pablo donde Juan Marcos se separa (Hch 13:13), el paso por Perge (Hch 13:14) y la predicación al regreso (Hch 14:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74476, 'spa', 'acerca de, sobre', 'Marca el tema o asunto del discurso: ''acerca de X'', ''sobre X'', ''con respecto a X''. Con 276 apariciones es abrumadoramente el sentido primario en el Nuevo Testamento, usado con genitivo. Enmarca la indagación de Herodes sobre el Cristo (Mt 2:8), las enseñanzas de Jesús y las discusiones epistolares. Todas las lenguas seleccionan vocabulario referencial, no espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74477, 'spa', 'por, en beneficio de', 'Indica propósito, beneficio o causa: ''por X'', ''en favor de X'', ''a causa de X''. Este sentido aparece 29 veces, frecuentemente en contextos sacrificiales o intercesores de gran peso teológico. Jesús dice que su sangre es derramada ''por muchos'' (Mt 26:28 — περὶ πολλῶν), y ora ''por'' Pedro (Lc 22:32). El español emplea ''por'' para distinguirlo del sentido referencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74479, 'spa', 'alrededor de (espacial)', 'Sentido espacial de rodear o circundar: ''alrededor de X'', usado con acusativo. Diecinueve apariciones conservan el núcleo etimológico del vocablo. Juan el Bautista lleva un cinturón ''alrededor de su cintura'' (Mt 3:4; Mc 1:6); una piedra de molino se cuelga ''alrededor del cuello'' (Mt 18:6); las multitudes se agolpan ''alrededor de'' Jesús (Mc 3:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74480, 'spa', 'aproximadamente, cerca de', 'Marca aproximación numérica o temporal: ''como, aproximadamente, cerca de'', usado con acusativo de medida. Nueve apariciones se concentran en la parábola de los obreros (Mt 20:3, 5, 6, 9 — ''como a la hora tercera'') y en la crucifixión (''como a la hora novena'', Mt 27:46). El español ''cerca de'' y ''como'' captan la imprecisión deliberada de estas referencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74497, 'spa', 'Recorrer, ir alrededor', 'Ir de un lugar a otro, recorrer o hacer un circuito por una región (intransitivo). Se usa para describir a Jesús recorriendo Galilea (Mateo 4:23; 9:35; Marcos 6:6), a los fariseos que cruzan mar y tierra para ganar un convertido (Mateo 23:15), y al cegado Elimas tanteando sin rumbo (Hechos 13:11). El español «recorría» capta este desplazamiento abarcador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74498, 'spa', 'Llevar consigo', 'Llevar a alguien consigo o conducir a una persona en los propios viajes (transitivo, causativo). En 1 Corintios 9:5, Pablo pregunta sobre el derecho apostólico de περιάγειν a una hermana como esposa, es decir, llevar a una esposa creyente en viajes misioneros. El español «llevar consigo» preserva la fuerza causativa: no solo ir uno mismo, sino traer a otra persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74501, 'spa', 'Quitar o remover', 'Quitar, remover o despojar: desprender algo que rodea o cubre un objeto, ya sea en sentido literal o figurado. El prefijo περι- le confiere un matiz de «desde alrededor», sugiriendo la remoción de algo que envuelve o circunda. En el relato del naufragio aparece tres veces: la esperanza es quitada (Hch 27:20), las anclas son soltadas (27:40) y las amarras son cortadas al zarpar (28:13). Pablo lo usa en 2 Corintios 3:16 para el velo que es quitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74503, 'spa', 'El participio perfecto pasivo que describe el estado resultante de estar vestido', 'El participio perfecto pasivo que describe el estado resultante de estar vestido o llevar puestas vestiduras. Es el sentido más frecuente (11 ocurrencias), dominando las visiones celestiales del Apocalipsis. Las vestiduras blancas de Ap 4:4, 7:9 y 7:13 y el joven en el sepulcro vacío ''vestido con una túnica blanca'' (Mar 16:5) ilustran esta cualidad estativa y adjetival.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74505, 'spa', 'El uso transitivo activo', 'El uso transitivo activo: vestir a otra persona, ponerle vestiduras a alguien más. Este sentido aparece en la escena del juicio de Mat 25:36-43 (''estuve desnudo y me vestisteis''), los soldados de Herodes vistiendo a Jesús con un manto espléndido (Luc 23:11), y los soldados colocándole un manto púrpura (Jn 19:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74507, 'spa', 'El uso en voz media y reflexiva', 'El uso en voz media y reflexiva: vestirse uno mismo, ponerse una prenda por propia acción. La pregunta retórica de Jesús sobre Salomón en Mat 6:29 (''ni siquiera Salomón se vistió como uno de estos'') y la orden del ángel a Pedro en Hch 12:8 (''ponte tu vestido'') ilustran el sentido autorreflexivo de la acción dirigida a uno mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74517, 'spa', 'Mirar alrededor', 'Mirar alrededor, dirigir la vista en derredor — acto deliberado de inspección visual dirigido a los presentes o al entorno. Exclusivo de Marcos en el NT (Marcos 3:5, 3:34, 5:32, 9:8, 10:23, 11:11), se emplea únicamente de Jesús y funciona como recurso narrativo que resalta su autoridad e intencionalidad. En Marcos 3:5 mira alrededor «con enojo» y en 5:32 busca identificar quién lo tocó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74521, 'spa', 'Envolver o atar', 'Atar o envolver algo alrededor de un objeto. La descripción de Juan sobre Lázaro saliendo del sepulcro con el rostro envuelto en un paño retrata vívidamente las costumbres funerarias de la época y la naturaleza milagrosa de su resurrección a pesar de los impedimentos físicos. Las glosas multilingües (''had-been-wrapped'', ''estaba-envuelto'', ''être-lié-autour'') captan la acción completada de envolver.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74522, 'spa', 'Entrometerse o curiosear', 'Actuar como entrometido o inmiscuirse en asuntos ajenos. La reprensión de Pablo aborda la ociosidad disfrazada de actividad, donde las personas pierden el tiempo interfiriendo en los asuntos de otros en vez de trabajar productivamente. La evidencia multilingüe (''being-busybodies'', ''entrometiéndose'') capta el comportamiento intrusivo que Pablo condena, contrastándolo con el trabajo honesto y la responsabilidad personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74524, 'spa', 'Andar errante', 'Las glosas multilingües destacan el movimiento itinerante: ambulantes, anduvieron, yendo de casa en casa en español; going about en inglés; umherziehen en alemán. El léxico señala significados que van desde «recorrer» hasta «vagar como mendigo». Hechos 19:13 describe a exorcistas itinerantes, 1 Timoteo 5:13 advierte sobre el ocio y Hebreos 11:37 honra a los perseguidos errantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74526, 'spa', 'Ceñirse para servir', 'Ceñirse alrededor de la cintura, sujetando las vestiduras con un cinturón en preparación para el servicio, el trabajo o la acción. El verbo evoca la práctica antigua de recoger las túnicas sueltas dentro del cinturón para moverse con libertad. El español «ceñir» (rodear, apretar) y el alemán «umgürten» (ceñir alrededor) subrayan la acción física envolvente. En Lucas 12:35 y 17:8, los siervos ceñidos representan fidelidad vigilante y disposición inmediata para obedecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74532, 'spa', 'Adornarse externamente', 'La acción de ponerse o vestirse adornos exteriores. La instrucción de Pedro a las mujeres cristianas destaca que la verdadera belleza no se encuentra en la decoración externa, sino en la cualidad imperecedera de un espíritu manso y tranquilo. Las glosas multilingües (''de-ponerse'') subrayan el acto de engalanarse, que Pedro subordina al carácter espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74533, 'spa', 'Rodear físicamente', 'Estar de pie alrededor formando un círculo o multitud en torno a alguien. En Juan 11:42 y Hechos 25:7, grupos rodean a Jesús y a Pablo respectivamente. El sentido concreto de cerco espacial se refleja en traducciones como «estar alrededor» o «rodear». La asignación al dominio MOVIMIENTO > Movimiento lineal subraya el posicionamiento físico involucrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74534, 'spa', 'Desecho o escoria', 'Lo que es despreciable y se desecha, basura que se descarta. La autodescripción de Pablo captura el desprecio del mundo hacia los apóstoles, tratados como desperdicios que hay que eliminar. Las glosas multilingües (''basura'', ''déchet'', ''Kehricht'') enfatizan consistentemente la idea de algo sin valor destinado al descarte, resaltando el contraste entre la evaluación mundana y la vocación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74535, 'spa', 'Cubrir completamente', 'La evidencia interlingüística subraya la idea de cobertura total: cubrir, cubierta alrededor en español; cover en inglés; verhüllen en alemán. El léxico lo define como «cubrir por todas partes», incluyendo envolver en vestiduras y metafóricamente tender «un velo de oscuridad sobre las acciones». Marcos 14:65 y Lucas 22:64 describen cómo vendaron los ojos de Jesús; Hebreos 9:4, el revestimiento del arca con oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74536, 'spa', 'Rodear o llevar puesto', 'Yacer alrededor, estar colocado en torno o llevar puesto, describiendo algo que ciñe o sujeta a una persona. Funciona como pasivo de περιτίθημι y expresa el estado de estar rodeado o ceñido. En Marcos 9:42 y Lucas 17:2, una piedra de molino «está colgada al cuello» como imagen de juicio devastador. Pablo lo usa en Hechos 28:20 para describir la cadena que lo ata, mientras Hebreos 12:1 lo aplica a la nube de testigos que envuelve a los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74538, 'spa', 'Dominio sobre algo', 'Tener control o dominio sobre algo. El relato del naufragio de Lucas emplea este término para describir el arduo esfuerzo de los marineros por asegurar el bote en medio de la tempestad, enfatizando la lucha por mantener el control en circunstancias caóticas. La evidencia multilingüe (''control'', ''dueños'') refleja el sentido de maestría y dominio, esencial para la supervivencia en la tormenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74539, 'spa', 'Ocultarse deliberadamente', 'Esconder u ocultar, frecuentemente a uno mismo. La reclusión de cinco meses de María tras la concepción sugiere un período de privacidad y reflexión sobre la obra divina en su interior. Las glosas multilingües (''se-ocultaba'', ''cacher'') enfatizan el retiro deliberado de la vida pública, invitando a reflexionar sobre la respuesta de María a la intervención de Dios en su vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74540, 'spa', 'Sitiar o cercar', 'Rodear o circundar, particularmente en un asedio militar. El lamento de Jesús sobre Jerusalén incluye esta profecía contundente de enemigos rodeando la ciudad, predicción trágicamente cumplida cuando Roma sitió Jerusalén. La evidencia multilingüe (''te-rodearán'', ''assiéger'') captura la imaginería militar del cerco, subrayando el juicio resultante del rechazo al Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74543, 'spa', 'Profundamente afligido', 'Sumamente triste o profundamente afligido, forma intensificada que expresa una tristeza abrumadora. El prefijo περι- amplifica la base λύπη (dolor, pena) para describir una aflicción que envuelve a la persona por completo. Jesús aplica esta palabra a sí mismo en Getsemaní (Mt 26:38; Mr 14:34), diciendo que su alma está περίλυπος «hasta la muerte», un dolor tan hondo que se siente mortal. Herodes experimenta este mismo estado al quedar atrapado por su juramento imprudente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74544, 'spa', 'Esperar con expectativa', 'Esperar o aguardar con expectativa. El último mandato de Jesús antes de su ascensión dirige a los discípulos a permanecer en Jerusalén, aguardando al Espíritu Santo prometido. Las traducciones multilingües (''esperar,'' ''attendre,'' ''to-wait-for'') enfatizan uniformemente la espera paciente, destacando la actitud de anticipación obediente de los discípulos antes de Pentecostés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74545, 'spa', 'En los alrededores', 'Alrededor, en la zona circundante o en los alrededores. La descripción de Lucas sobre las multitudes procedentes de las ciudades vecinas resalta el alcance geográfico del ministerio de sanidad apostólico, cuya fama se extendió por toda la región. La evidencia multilingüe (''surrounding,'' ''circundantes,'' ''autour'') capta uniformemente la proximidad espacial y la geografía envolvente que atraía a la gente hacia los apóstoles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74546, 'spa', 'Vecinos cercanos', 'Quienes habitan alrededor o cerca; vecinos. El relato de Lucas muestra cómo los acontecimientos extraordinarios del nacimiento de Juan el Bautista se difundieron por la comunidad local, mientras los vecinos presenciaban la obra de Dios en el hogar de Zacarías. Las traducciones multilingües (''dwelling-around,'' ''que-habitaban-alrededor,'' ''voisin'') subrayan la proximidad y la comunidad, destacando cómo los actos de Dios impactan a quienes viven cerca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74547, 'spa', 'Vecinos colindantes', 'Vecinos o quienes habitan cerca. El relato de Lucas muestra el gozo comunitario cuando los vecinos supieron de la misericordia de Dios hacia Elisabet en su concepción y parto milagrosos. La evidencia multilingüe (''neighbors,'' ''vecinos,'' ''voisin'') enfatiza consistentemente la proximidad y la vida comunitaria compartida, destacando los lazos sociales que convirtieron la bendición de Elisabet en motivo de celebración colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74548, 'spa', 'Pueblo escogido especial', 'Especial o peculiar, que denota un pueblo que pertenece de manera única a Dios. La descripción de Pablo recurre a la imaginería de Éxodo y Deuteronomio sobre Israel como posesión atesorada de Dios, aplicada ahora a la comunidad redimida. Las traducciones multilingües (''special,'' ''especial,'' ''auserwaehltes-Volk'') captan el sentido de distinción escogida, subrayando a los creyentes como posesión propia de Cristo, purificados y celosos de buenas obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74549, 'spa', 'Pasaje o sección textual', 'Un pasaje o sección de un escrito. La narrativa de Lucas identifica la porción específica de la Escritura que el etíope leía, la cual se convirtió en el fundamento para la explicación evangelística de Felipe. La evidencia multilingue (''passage'', ''porción'') enfatiza consistentemente una sección textual definida, resaltando cómo la Palabra escrita de Dios sirvió como punto de partida para la proclamación del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74550, 'spa', 'Caminar físicamente', 'Sentido literal, físico: desplazarse a pie, caminar hacia algún lugar. Jesús caminando sobre el mar (Mt 14:25), el paralítico sanado caminando (Mt 9:5) y las multitudes caminando por los caminos emplean este significado concreto. Con 47 ocurrencias, el sentido físico casi iguala al figurado en frecuencia, recordándonos que la metáfora permanece anclada en lo corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74553, 'spa', 'Conducirse, vivir', 'Sentido figurado: conducirse, vivir o comportarse de una manera particular. Casi la mitad de las ocurrencias (48 veces) describen un modo de vida: andar en tinieblas o en luz (Jn 12:35), andar conforme a la carne o al Espíritu (Ro 8:4), andar dignamente de la vocación (Ef 4:1). Marcos 7:5 lo usa para seguir las tradiciones de los ancianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74572, 'spa', 'Rondar, acechar', 'Una única ocurrencia en 1 Pe 5:8 donde el diablo ''anda alrededor'' (περιπατεῖ) como león rugiente buscando a quien devorar. El español ''anda alrededor'' enfatiza un merodeo inquieto y depredador: ni mero caminar físico ni conducta ética, sino un acecho amenazante e intencional que fusiona movimiento literal con intención maligna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74593, 'spa', 'Traspasar con dolores', 'Traspasar o atravesar a uno mismo, aquí metafóricamente con pesares. La advertencia de Pablo sobre el amor al dinero emplea una imagen vívida de dolor autoinfligido, pues la codicia no trae felicidad sino múltiples aflicciones. Las glosas multilingues (''pierced-through'', ''traspasaron'') subrayan la naturaleza penetrante y hiriente del sufrimiento que resulta de perseguir las riquezas por encima de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74594, 'spa', 'Caer en situación', 'Las glosas multilingües destacan el sentido de encontrarse o caer en algo: caigáis, cayó, habiendo caído en español; fell, fall into en inglés; begegnen en alemán. El léxico señala significados desde «caer alrededor» hasta «encontrarse con» y el choque de naves en el mar. Lucas 10:30 describe al viajero que cayó entre ladrones; Hechos 27:41, el naufragio; Santiago 1:2, las pruebas de la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74595, 'spa', 'Preservar y adquirir', 'La evidencia multilingue muestra tanto preservacion como adquisicion. El lexico define el termino como «guardar, preservar» y «procurar, asegurar, obtener». Lc 17:33 habla de preservar la vida, Hch 20:28 de adquirir la iglesia con sangre, y 1 Ti 3:13 de ganar una buena posicion. La voz media enfatiza el interes personal en la accion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74596, 'spa', 'Obtención y posesión', 'Obtención, adquisición o preservación: el acto de ganar posesión de algo o el estado de ser resguardado. El término une dos ideas clave en el NT: (a) la obtención activa de la salvación, como en 1 Tesalonicenses 5:9 («Dios nos ha destinado para alcanzar la salvación») y 2 Tesalonicenses 2:14 («alcanzar la gloria de nuestro Señor Jesucristo»), y (b) el estado de ser posesión atesorada de Dios, como en Efesios 1:14 y 1 Pedro 2:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74597, 'spa', 'Arrancar la ropa violentamente', 'Arrancar o rasgar la ropa de manera violenta. El relato de Lucas sobre el castigo de Pablo y Silas en Filipos incluye este detalle de humillación pública, cuando les fueron arrancadas las vestiduras antes de los azotes. La evidencia multilingue (''having-torn-off'', ''rasgando'', ''déchirer'') capta la acción violenta y humillante que precedió al castigo físico, subrayando el sufrimiento de los apóstoles por causa del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74598, 'spa', 'Distraerse por afanes', 'Estar distraído o ser apartado por muchas tareas. El relato de Lucas sobre la queja de Marta revela cómo el servicio puede convertirse en distracción cuando desvía la atención de Jesús mismo. Las glosas multilingues (''was-distracted'', ''estaba-distraída'', ''être-distrait'') enfatizan consistentemente el ser jalado en múltiples direcciones, resaltando la corrección amorosa de Jesús: una sola cosa es necesaria, la presencia atenta ante él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74599, 'spa', 'Abundancia desbordante', 'Abundancia o excedente, ya sea de gracia, gozo o incluso de maldad. Romanos 5:17 habla de la sobreabundancia de gracia que permite a los creyentes reinar en vida por medio de Cristo. En 2 Corintios 8:2 y 10:15, el término expresa generosidad desbordante y fe en expansión. Santiago 1:21 lo emplea negativamente para referirse al exceso de maldad. La idea nuclear es la de una medida que rebasa lo ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74600, 'spa', 'Abundancia y excedente', 'Abundancia, excedente o desbordamiento: lo que rebosa, sobra o brota de la plenitud. En el NT tiene usos concretos y abstractos. En Mar 8:8 se refiere a los fragmentos sobrantes (κλασμάτων περισσεύματα) tras la alimentación de los cuatro mil. En sentido figurado, Jesús enseña que «de la abundancia (περίσσευμα) del corazón habla la boca» (Mat 12:34; Luc 6:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74601, 'spa', 'Abundar, rebosar — estar presente en abundancia, rebosar o aumentar grandemente', 'Abundar, rebosar — estar presente en abundancia, rebosar o aumentar grandemente: el sentido intransitivo dominante. Se aplica a personas que tienen de sobra (Lucas 15:17, «pan de sobra»), a cualidades como la gracia o el pecado que se multiplican (Romanos 5:15; 6:1), y a la exhortación de Pablo a «abundar en la obra del Señor» (1 Corintios 15:58). El español «abundar» capta la idea de exceder la medida normal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74603, 'spa', 'Sobrar, quedar de más — quedar como sobrante después de que una necesidad ha sid', 'Sobrar, quedar de más — quedar como sobrante después de que una necesidad ha sido satisfecha. Este es el sentido de «las sobras», prominente en los relatos de la alimentación: doce canastas de fragmentos «sobraron» (Mateo 14:20; Lucas 9:17). Marcos 12:44 y Lucas 21:4 invierten la imagen: la viuda dio no de su sobrante sino de su pobreza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74612, 'spa', 'Hacer abundar, prodigar — el sentido causativo-transitivo', 'Hacer abundar, prodigar — el sentido causativo-transitivo: hacer que algo abunde o prodigarlo sobre alguien. Dios es típicamente el sujeto: «Dios puede hacer que toda gracia abunde para vosotros» (2 Corintios 9:8), «la cual hizo sobreabundar para con nosotros» (Efesios 1:8). 1 Tesalonicenses 3:12 recoge la oración de Pablo de que el Señor haga abundar el amor mutuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74626, 'spa', 'Recibir abundancia (pasivo) — el sentido pasivo o pasivo divino', 'Recibir abundancia (pasivo) — el sentido pasivo o pasivo divino: recibir abundancia, que se le conceda más. Presente en el enigmático dicho de Jesús: «Al que tiene, más se le dará, y tendrá en abundancia» (Mateo 13:12; 25:29). Este pasivo enmarca la abundancia como don recibido, no como algo generado por uno mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74632, 'spa', 'El núcleo comparativo', 'El núcleo comparativo: más, mayor, que excede en grado o cantidad. Jesús pregunta ''¿Qué hacéis de más que los demás?'' (Mat 5:47), y el escriba afirma que el amor supera a todos los holocaustos (Mar 12:33). Este es el uso más frecuente del término — medir una cosa contra otra y hallarla superior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74637, 'spa', 'Uso adverbial o intensivo que denota medida excesiva o abundancia extraordinaria', 'Uso adverbial o intensivo que denota medida excesiva o abundancia extraordinaria. Los discípulos quedaron ''sobremanera asombrados'' (Mar 6:51), el hombre sanado proclamaba la noticia ''tanto más'' a pesar de que le dijeron callar (Mar 7:36), y Jesús promete vida ''en abundancia'' (Jn 10:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74638, 'spa', 'Lo que excede la necesidad y por tanto resulta superfluo o innecesario', 'Lo que excede la necesidad y por tanto resulta superfluo o innecesario. Pablo dice a los corintios que es ''superfluo'' seguir escribiéndoles sobre la colecta (2 Co 9:1). El excedente aquí no es abundancia bienvenida sino redundancia, y el mismo significado raíz — ''más allá de lo necesario'' — adquiere un tono desestimativo en lugar de celebratorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74641, 'spa', 'Uso sustantivado que denota ventaja, beneficio o preeminencia — el ''valor excede', 'Uso sustantivado que denota ventaja, beneficio o preeminencia — el ''valor excedente'' de una condición o estatus. Pablo abre Romanos 3 preguntando ''¿Cuál es, pues, la ventaja del judío?'' (Rom 3:1). El exceso aquí no es de cantidad sino de privilegio — lo que una parte tiene y la otra carece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74643, 'spa', 'Expresión de un grado que sobrepasa lo ordinario o esperado', 'Expresión de un grado que sobrepasa lo ordinario o esperado: ''sobremanera'', ''mucho más'', ''sin medida''. En contextos narrativos marca una escalada emocional o retórica, como cuando la multitud grita ''mucho más'' (Mr 15:14) o los discípulos se asombran ''sobremanera'' (Mr 10:26). Abarca tanto la dimensión absoluta (''excesivamente'') como la comparativa (''aún más, todavía más'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74648, 'spa', 'Paloma, pichón — la paloma o pichón común, empleado tanto en sentido literal com', 'Paloma, pichón — la paloma o pichón común, empleado tanto en sentido literal como figurado. Los usos literales incluyen las aves sacrificiales vendidas en los recintos del templo (Mt 21:12; Mc 11:15; Jn 2:14-16) y la ofrenda de María de un par de palomas (Lc 2:24). Los usos figurados abarcan el descenso del Espíritu Santo «como paloma» en el bautismo de Jesús (Mt 3:16; Mc 1:10; Lc 3:22; Jn 1:32) y la instrucción proverbial de ser «sencillos como palomas» (Mt 10:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74651, 'spa', 'Ser circuncidado (voz pasiva/media)', 'Ser circuncidado (voz pasiva/media): someterse a o recibir la circuncisión, ya sea como rito físico del pacto mosaico o en sentido espiritual/figurado. Este es el sentido que domina la controversia apostólica: los creyentes fariseos insisten en que los gentiles deben ''ser circuncidados'' (Hch 15:1, 5), Pablo resiste la imposición de circuncidarse sobre Tito (Gá 2:3) y declara que si os circuncidáis, Cristo de nada os aprovechará (Gá 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74652, 'spa', 'Circuncidar (voz activa)', 'Circuncidar (voz activa): realizar el acto de la circuncisión sobre alguien, cortando el prepucio como acto pactal o ritual. Abraham circuncidó a Isaac al octavo día (Hch 7:8), los vecinos quisieron circuncidar a Juan conforme a la costumbre (Lc 1:59) y Jesús fue circuncidado al octavo día (Lc 2:21). Moisés os dio la circuncisión y circuncidáis al hombre en sábado (Jn 7:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74665, 'spa', 'Poner alrededor, colocar', 'Poner o colocar algo alrededor, encima o sobre una persona u objeto. En los relatos de la Pasión, este verbo describe a los soldados poniendo un manto púrpura sobre Jesús (Mt 27:28, Mr 15:17, Jn 19:2) y colocando una esponja con vinagre en una caña para acercarla a su boca (Mt 27:48, Mr 15:36). En las parábolas de la viña, describe el cercar con un vallado (Mt 21:33, Mr 12:1). Pablo lo emplea metafóricamente para revestir de honor a los miembros menos estimados del cuerpo (1 Co 12:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74672, 'spa', 'Circuncisión — el rito de cortar el prepucio como señal de pertenencia al pacto,', 'Circuncisión — el rito de cortar el prepucio como señal de pertenencia al pacto, y por extensión el pueblo judío o la comunidad del pacto definida por dicho rito. Juan 7:22-23 lo remonta a los patriarcas; Hechos 10:45 y 11:2 lo usan como etiqueta grupal («los de la circuncisión»). El argumento teológico de Pablo en Romanos 2:25-29 y Gálatas 5:6 redefine el término espiritualmente, afirmando que la «circuncisión del corazón» supera al rito externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74678, 'spa', 'Trastornar o enloquecer', 'Hacer girar o llevar a alguien a la locura, o trastornar y perturbar. La exclamación de Festo refleja su incapacidad para comprender la proclamación de Pablo sobre la resurrección de Cristo, atribuyéndola a inestabilidad mental por exceso de estudio. La evidencia multilingue (''is-turning'', ''te-trastornan'', ''rendre-fou'') capta el sentido de llevar a la locura, revelando cómo el evangelio parecía insensatez ante la mentalidad romana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74679, 'spa', 'Correr por todas partes', 'Correr de un lado a otro con urgencia y amplitud. La descripción de Marcos muestra a las multitudes recorriendo toda la región para llevar a los enfermos ante Jesús, reflejando el fervor y la esperanza que su ministerio sanador generaba. Las glosas multilingües (''recorrieron,'' ''courir-de-tous-côtés,'' ''umherlaufen'') destacan este movimiento apresurado y generalizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74680, 'spa', 'Llevar de un lado a otro', 'La evidencia multilingue destaca movimiento y transporte. El lexico define el termino como «llevar alrededor», incluyendo «cargar consigo», «pasar de mano en mano» y «mover en derredor». Mr 6:55 describe el transporte fisico de enfermos, 2 Co 4:10 el sentido espiritual de sobrellevar sufrimientos, y Ef 4:14 el ser arrastrado por doctrinas falsas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74681, 'spa', 'Despreciar o menospreciar', 'Despreciar o tratar con desdén. La exhortación de Pablo a Tito subraya la necesidad de una enseñanza con autoridad que inspire respeto, evitando que los oyentes desestimen o miren con desprecio al joven ministro. La evidencia interlingüística (''menosprecie,'' ''verachten,'' ''let-disregard'') refleja consistentemente el descrédito y el menosprecio que Pablo instruye a Tito a prevenir mediante una proclamación fiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74682, 'spa', 'Región circundante', 'La región circundante, comarca o distrito que rodea un lugar determinado, sustantivo femenino derivado del adjetivo que significa «de alrededor». En los Evangelios designa sistemáticamente el área geográfica en torno a una ciudad, río o territorio: la región del Jordán (Mt 3:5, Lc 3:3), la tierra de Genesaret (Mt 14:35) o la campiña galileana (Mr 1:28, Lc 4:14, 4:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74686, 'spa', 'Desecho o escoria', 'Desecho o basura, lo que se barre y se descarta como inservible. La cruda autodescripción de Pablo revela cómo el mundo percibe el ministerio apostólico: como lo más bajo y despreciable. Las glosas multilingües (''desperdicio,'' ''déchet,'' ''Abschaum'') subrayan uniformemente la condición de rechazo y carencia de valor, destacando la naturaleza invertida del reino de Dios donde los despreciados llegan a ser honrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74687, 'spa', 'Jactarse con arrogancia', 'Jactarse o presumir con arrogancia. La descripción paulina de la naturaleza del amor incluye la característica negativa de que el amor no se entrega a la autoexaltación presuntuosa ni a la exhibición vanidosa. La evidencia interlingüística (''se-jacta,'' ''se-vanter,'' ''sich-aufblasen'') enfatiza consistentemente la autoexaltación orgullosa, en marcado contraste con la humildad y la entrega al prójimo que caracterizan al amor genuino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74688, 'spa', 'Nombre propio femenino', 'Nombre personal de una mujer cristiana en Roma, elogiada por Pablo por su arduo trabajo en el Señor. El nombre indica un trasfondo persa, y el saludo afectuoso de Pablo (''la amada'') junto con el reconocimiento de su labor demuestra que era una colaboradora valiosa en el ministerio del evangelio, ilustrando el papel significativo de las mujeres en la iglesia apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74690, 'spa', 'Aves colectivamente, las criaturas aladas del cielo, abarcando las aves silvestr', 'Aves colectivamente, las criaturas aladas del cielo, abarcando las aves silvestres en general sin referirse a ninguna especie en particular. En la enseñanza de Jesús, sirven como ejemplo de la providencia divina (Mt 6:26, ''las aves del cielo'') y como agentes parabólicos (Mt 13:4, aves que devoran la semilla; Mt 13:32, aves que anidan en las ramas). La evidencia interlingüística es uniforme: las 14 ocurrencias neotestamentarias apuntan a un solo sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74692, 'spa', 'Volar', 'Volar: la acción de surcar o desplazarse por el aire con alas. Las cinco ocurrencias neotestamentarias aparecen en la imaginería apocalíptica de Apocalipsis, otorgándole al término un registro visionario y cósmico. El cuarto ser viviente se asemeja a un águila en vuelo (Ap 4:7). Un águila vuela por el cenit anunciando tres ayes (8:13). La mujer perseguida recibe alas para volar al desierto (12:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74693, 'spa', 'Una gran masa sólida de piedra —roca madre, acantilado o formación rocosa— en co', 'Una gran masa sólida de piedra —roca madre, acantilado o formación rocosa— en contraposición a una piedra suelta o labrada (λίθος). Usada literalmente para la roca sobre la que el hombre prudente edifica (Mt 7:24-25), el sepulcro labrado en la roca (Mt 27:60) y las rocas que se partieron en la crucifixión (Mt 27:51). Metafóricamente es fundacional en Mt 16:18 (''sobre esta roca edificaré mi iglesia'') y en la identificación paulina de la roca del desierto con Cristo (1 Co 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74697, 'spa', 'Pedro (nombre propio)', 'Nombre propio de Simón Pedro, el principal de los Doce apóstoles, a quien Jesús dio el nombre Πέτρος (''Roca'') como traducción del arameo Kefá (Jn 1:42; Mt 16:18). Usado 156 veces en todos los casos gramaticales, aparece en los relatos de su llamamiento (Mt 4:18), su confesión (Mt 16:16), su negación (Mt 26:69-75) y su liderazgo en la iglesia primitiva (Hch 2:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74700, 'spa', 'Terreno pedregoso', 'Terreno rocoso o pedregoso, específicamente suelo poco profundo sobre roca madre donde las plantas brotan rápido pero no logran echar raíces profundas. Las cuatro ocurrencias aparecen en la parábola del sembrador (Mat 13:5, 20; Mar 4:5, 16), donde simboliza a quienes reciben la palabra con alegría pero desertan bajo la tribulación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74701, 'spa', 'Hierba ruda', 'La ruda, planta de jardín con hojas aromáticas. La crítica de Jesús a la escrupulosidad farisaica emplea la ruda como ejemplo de un diezmo meticuloso sobre hierbas insignificantes, contrastado con el abandono de los asuntos de mayor peso. Las glosas multilingües («rue», «ruda») identifican esta planta botánica específica, subrayando cómo la precisión religiosa puede encubrir la falta de verdadera transformación interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74703, 'spa', 'Manantial, fuente, surgencia de agua', 'Manantial, fuente, surgencia de agua. Un manantial o fuente literal, una fuente natural de la que brota agua. El pozo de Jacob en Sicar se llama πηγή (Juan 4:6), y las visiones de juicio del Apocalipsis tienen como blanco ríos y manantiales (Apocalipsis 8:10; 14:7; 16:4). La descripción de los falsos maestros en 2 Pedro 2:17 como ''fuentes sin agua'' depende de este sentido literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74706, 'spa', 'Erigir o plantar', 'Plantar o levantar, particularmente una tienda o tabernáculo. El autor de Hebreos emplea este término para destacar que el verdadero santuario celestial fue establecido por Dios mismo, no por construcción humana. Las glosas multilingües («pitched», «erigió», «aufschlagen») señalan consistentemente la acción de instalar o establecer, resaltando la agencia divina en la creación del auténtico lugar de adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74709, 'spa', 'Lodo, barro', 'Lodo o barro: tierra blanda y húmeda capaz de ser moldeada o aplicada sobre una superficie. El español distingue entre «lodo» (tierra sin forma) y «barro» (arcilla trabajable), mientras que el francés usa «boue» (lodo) y el alemán «Lehm» enfatiza la cualidad de arcilla de alfarero. Las seis apariciones neotestamentarias se concentran en Juan 9:6-15, donde Jesús forma barro con saliva y lo aplica a los ojos del ciego como acto de sanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74711, 'spa', 'Alforja de viajero', 'Bolsa o alforja de cuero usada por viajeros para llevar provisiones, el equipamiento habitual de quien emprende un camino. El español «alforja» (morral, talego), el francés «besace» (bolsa de mendigo con dos compartimentos) y el alemán «Reisetasche» (bolsa de viaje) destacan matices distintos: la capacidad de carga, el estilo de vida itinerante o el viaje mismo. Todos los usos neotestamentarios (Mt 10:10; Mr 6:8; Lc 9:3; 10:4; 22:35-36) involucran la prohibición de Jesús de llevarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74712, 'spa', 'Codo (medida)', 'Codo, unidad de medida lineal basada en la longitud del antebrazo. En Mat 6:27 y Luc 12:25, Jesús lo emplea metafóricamente: nadie puede añadir un codo a su vida por medio de la preocupación. Juan 21:8 lo usa como distancia literal (unos 200 codos desde la orilla), y Apocalipsis 21:17 especifica la medida del muro de la ciudad celestial en 144 codos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74713, 'spa', 'Prender, arrestar o aprehender a una persona, típicamente en contextos de acción', 'Prender, arrestar o aprehender a una persona, típicamente en contextos de acción hostil o legal. Este es el uso dominante en el NT, concentrado en el Evangelio de Juan donde las autoridades judías intentan arrestar a Jesús. Pasajes clave: Jn 7:30, 7:32, 10:39. El matiz es de fuerza y confrontación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74716, 'spa', 'Pescar o atrapar animales, una aplicación concreta de la idea raíz de agarrar al', 'Pescar o atrapar animales, una aplicación concreta de la idea raíz de agarrar algo que escapa. Se encuentra exclusivamente en la narración de la pesca posterior a la resurrección (Jn 21:3, 10), donde el sentido cambia del arresto legal a la captura física de peces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74720, 'spa', 'Comprimir o apretar', 'Apretar o comprimir, especialmente al medir grano. La enseñanza de Jesús sobre la generosidad recurre a la imagen comercial de prensar el grano para que quepa más en la medida, simbolizando la retribución abundante de Dios ante la entrega sacrificial. La evidencia multilingüe («pressed-down», «apretada», «tassé») capta la acción de compactar para aumentar la cantidad, ilustrando la naturaleza extravagante y desbordante de la generosidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74721, 'spa', 'Retórica engañosa', 'Discurso persuasivo o plausible que puede engañar. La advertencia de Pablo en Colosenses alerta a los creyentes sobre el peligro de dejarse llevar por enseñanzas elocuentes pero falsas, que suenan convincentes pero alejan de Cristo. La evidencia multilingüe («persuasive-speech», «palabras-persuasivas») subraya la habilidad retórica capaz de encubrir el error, destacando la necesidad de discernimiento y arraigo en la verdad apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74722, 'spa', 'Amargar o amargarse', 'Hacer amargo o volverse amargado, abarcando tanto el sabor físico como la disposición emocional. Apocalipsis 8:11 describe aguas hechas literalmente amargas por la estrella caída, mientras que Ap 10:9-10 retrata el estómago del profeta amargado por el rollo ingerido. Colosenses 3:19 usa el término en sentido relacional: los esposos no deben amargarse contra sus esposas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74723, 'spa', 'Amargura moral', 'Amargura como condición moral y emocional: resentimiento, hostilidad o veneno interior. Hechos 8:23 la emplea junto a «hiel» para describir el corazón corrompido de Simón el Mago, haciendo eco de Deuteronomio 29:18. Romanos 3:14 cita el Salmo 10:7 sobre bocas llenas de amargura. Efesios 4:31 la incluye entre actitudes que el creyente debe desechar, y Hebreos 12:15 advierte de una «raíz de amargura» que contamina a muchos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74726, 'spa', 'Pilato (Poncio Pilato)', 'El prefecto romano de Judea (ca. 26-36 d.C.) que presidió el juicio y la crucifixión de Jesús. Pilato aparece en los cuatro relatos de la Pasión (Mt 27; Mr 15; Lc 23; Jn 18-19), en la nota cronológica de Lucas (Lc 3:1) y en la confesión credal de 1 Ti 6:13. El español ''Pilato'' y el alemán ''Pilatus'' conservan consistentemente el cognomen latino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74729, 'spa', 'Hincharse por veneno', 'Se refiere a la hinchazón o inflamación física esperada tras la mordedura de una serpiente venenosa. La única aparición en el Nuevo Testamento muestra a los observadores malteses aguardando que el cuerpo de Pablo exhiba esta reacción natural al veneno, lo cual milagrosamente nunca ocurre. El vocabulario médico griego refleja aquí la comprensión antigua de los síntomas del envenenamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74730, 'spa', 'Tablilla de escritura', 'La tablilla de escritura que Zacarías solicita para comunicar el nombre de su hijo, Juan, al no poder hablar. Las traducciones multilingües (''writing-tablet'' en inglés, ''tablilla'' en español, ''tablette'' en francés) destacan su función como instrumento de comunicación. Este humilde objeto se convierte en el medio por el cual se proclama el decreto divino sobre el nombre del niño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74731, 'spa', 'Bandeja o fuente', 'Bandeja o fuente grande y plana para servir alimentos. Su uso neotestamentario está dominado por una escena estremecedora: la petición de Salomé de la cabeza de Juan el Bautista «ἐπὶ πίνακι» (Mt 14:8, 11; Mr 6:25, 28). Un utensilio ordinario de banquete se convierte en instrumento de horror, subrayando el colapso moral de Herodes. Lucas 11:39 lo usa en la reprensión de Jesús a los fariseos por su hipocresía exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74732, 'spa', 'Beber (literal o figurado)', 'Uso que abarca tanto lo literal como lo figurado, empleado para beber agua, vino u otras bebidas en contextos cotidianos y festivos, y figuradamente para participar en el sufrimiento de Cristo, recibir sustento espiritual y compartir el pacto eucarístico. Las tres acepciones convergen en un único acto: consumir lo que se ofrece, ya sea copa terrenal o celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74764, 'spa', 'Riqueza nutritiva', 'La cualidad rica y nutritiva de la raíz del olivo en la que participan las ramas gentiles según Romanos 11:17. Las traducciones oscilan entre ''gordura'' literal (inglés, francés ''graisse'') y ''riqueza'' metafórica (español, alemán ''Fettigkeit''), reflejando el doble alcance literal-figurado del término. La metáfora de Pablo presupone conocimiento del cultivo del olivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74765, 'spa', 'Vender', 'Vender bienes, propiedades o personas por dinero, abarcando transacciones comerciales ordinarias y la práctica más severa de vender personas como esclavos por deuda. Pasajes clave incluyen al mercader que vende todo por la perla (Mt 13:46), la sugerencia de vender el ungüento costoso para caridad (Mt 26:9, Mr 14:5, Jn 12:5), la venta de gorriones en el mercado (Lc 12:6) y la familia del deudor vendida para saldar lo adeudado (Mt 18:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74772, 'spa', 'Postrarse, caer en adoración', 'Caer en postración, adoración o sumisión reverente: con 54 ocurrencias es el sentido dominante. Los magos se postran ante el niño Jesús (Mt 2:11), el leproso cae ante él suplicando sanidad, y en Apocalipsis los adoradores caen repetidamente ante el trono. El griego usa consistentemente πίπτω con ἐπὶ πρόσωπον (''sobre el rostro'') o πρὸς τοὺς πόδας (''a los pies'') como marcadores colocacionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74775, 'spa', 'Caer, desplomarse físicamente', 'Caer físicamente desde una altura o caer al suelo: 20 ocurrencias que cubren objetos y personas en movimiento descendente literal. Un gorrión cae a tierra (Mt 10:29), la semilla cae en terreno pedregoso (Mt 13:5), las migajas caen de la mesa del amo (Mt 15:27) y una persona cae en un hoyo (Mt 15:14). Sin matiz metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74776, 'spa', 'Derrumbarse, ser destruido', 'Derrumbarse, ser destruido o caer en ruina: 5 ocurrencias aplicadas a estructuras, ciudades y reinos. La casa edificada sobre la arena ''cayó'' con gran estrépito (Lc 6:49), y el estribillo apocalíptico ''¡Caída, caída es Babilonia la grande!'' (Ap 14:8; 18:2) hace eco directo de Isaías 21:9. La duplicación ''¡Caída, caída!'' subraya la totalidad de la destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74781, 'spa', 'Caer sobre, abatirse', 'Caer sobre alguien o venir encima: 3 ocurrencias donde πίπτω lleva una fuerza volitiva o imprecatoria en lugar de descenso accidental. En Lucas 23:30 los condenados claman ''¡Montes, caed sobre nosotros!'' (imperativo); en Apocalipsis 6:16 se repite la misma súplica desesperada. Hechos 15:16 cita Amós 9:11 sobre reedificar ''lo que ha caído'' (el tabernáculo de David).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74782, 'spa', 'Tropezar, caer moralmente', 'Caer moral o espiritualmente: tropezar en pecado, fracasar o caer de un estado de gracia. Nueve ocurrencias concentradas en las epístolas paulinas y la enseñanza de Jesús. El pasaje clave es Romanos 11:11: ''¿Tropezaron para caer?'', donde πίπτω conlleva ruina irrevocable en contraste con el tropiezo temporal. La advertencia de Pablo en 1 Corintios 10:12 (''el que piensa estar firme, mire que no caiga'') amplifica esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74802, 'spa', 'creer, tener fe en', 'El sentido primario abrumador (233 veces): creer en, confiar o tener fe en Dios, Cristo, una persona o un mensaje. Abarca todas las inflexiones de voz activa. La construcción πιστεύω εἰς (''creer en/hacia'') es distintivamente joánica y expresa entrega personal. Pasajes clave incluyen Mc 16:16 (''el que creyere y fuere bautizado''), Jn 3:16 y Ro 10:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74829, 'spa', 'ser encomendado', 'El sentido pasivo ''ser encomendado'' (6 veces), donde el sujeto recibe un encargo o administración. En Romanos 3:2 a los judíos ''les fueron confiados los oráculos de Dios'', y en Gálatas 2:7 a Pablo ''le fue encomendado el evangelio para los incircuncisos''. No se trata de fe sino de responsabilidad fiduciaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74837, 'spa', 'ser creído (pasivo)', 'El significado pasivo ''ser creído'' o ''ser aceptado como veraz'' (3 veces), donde un mensaje o persona es el sujeto gramatical. En 1 Timoteo 3:16 Cristo ''fue creído en el mundo'', y en 2 Tesalonicenses 1:10 el testimonio ''fue creído''. El paso de la confianza personal (sentido 1) a la recepción pública marca esta acepción como distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74867, 'spa', 'encomendar, confiar a', 'El sentido activo ''encomendar, confiar a'' (2 veces), donde uno entrega algo o a alguien al cuidado de otro. En Juan 2:24 Jesús ''no se confiaba'' a la multitud, y en Lucas 16:11 se pregunta ''¿quién os confiará lo verdadero?''. Esto invierte la dirección de la confianza: no recibirla sino otorgarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74875, 'spa', 'fe, confianza, creencia', 'La disposición subjetiva de confianza, seguridad y creencia dirigida hacia Dios, Cristo o el mensaje del evangelio — el concepto soteriológico central del NT. Con 239 apariciones, abarca las narraciones sinópticas de sanación (Mt 8:10; Mt 9:22, ''tu fe te ha salvado''), la teología paulina de la justificación (Ro 1:17; Gá 2:16) y la fe como depósito apostólico (Jud 3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74877, 'spa', 'fidelidad, fiabilidad', 'Fidelidad o fiabilidad como cualidad objetiva de carácter, no como acto subjetivo de creer. Cuatro apariciones en contextos reveladores: Ro 3:3 (''la fidelidad de Dios'' — su fiabilidad, no la creencia humana), Gá 5:22 (πίστις como fruto del Espíritu junto al amor y la bondad — claramente una virtud), Mt 23:23 (justicia, misericordia y fidelidad — lo ''más importante de la ley'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74879, 'spa', 'Fiel, digno de confianza', 'Sentido pasivo: fiel, confiable, seguro — describiendo personas, a Dios o declaraciones en las que se puede confiar. Las parábolas de Jesús valoran al siervo πιστός que administra bien los recursos (Mt 24:45; 25:21, 23). Pablo lo aplica al carácter de Dios (1 Co 1:9; 10:13; 1 Ts 5:24) y a fórmulas doctrinales (''fiel es la palabra'', 1 Ti 1:15; 2 Ti 2:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74881, 'spa', 'Creyente, el que cree', 'Sentido activo: creyente, que ejerce la fe — persona que confía en Dios o en Cristo, miembro de la comunidad creyente. El Señor resucitado dice a Tomás ''no seas incrédulo, sino creyente'' (πιστός, Jn 20:27). En Hechos y las Epístolas, οἱ πιστοί se convierte en designación técnica para los cristianos (Hch 10:45; 1 Ti 4:10, 12; 6:2). El español ''creyente/creyentes'' frente a ''fiel'' diferencia claramente esta acepción activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74889, 'spa', 'Convicción firme', 'La firme convicción de Timoteo acerca de las verdades que ha aprendido, enfatizada en 2 Timoteo 3:14. La evidencia multilingüe muestra distintos matices: el español resalta el proceso de enseñanza (''de-lo-que-fuiste-convencido''), mientras que el inglés y el alemán se centran en la certeza resultante (''were-convinced-of'', ''versichert-werden''). Esta convicción constituye el fundamento de la perseverancia de Timoteo en el ministerio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74890, 'spa', 'Ser engañado, ser inducido al error — el sentido pasivo donde el sujeto es vícti', 'Ser engañado, ser inducido al error — el sentido pasivo donde el sujeto es víctima del engaño de otro. «No os engañéis» advierte Pablo (1 Corintios 6:9; 15:33; Gálatas 6:7), y Lucas 21:8 registra la precaución de Jesús contra ser extraviados por impostores. La construcción pasiva y el imperativo repetido «no seáis engañados» enmarcan esto como una vulnerabilidad contra la que hay que guardarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74891, 'spa', 'Engañar, extraviar — engaño activo', 'Engañar, extraviar — engaño activo: causar deliberadamente que otros crean una falsedad o sigan un camino equivocado. Jesús advierte que muchos vendrán «engañando a muchos» (Mateo 24:5, 11), y 1 Juan 2:26 habla de quienes «intentan engañaros». El agente siempre es identificable: un falso profeta, una figura anticristiana o un poder demoníaco. El español «engañar» destaca la naturaleza intencional y causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74894, 'spa', 'Descarriarse, errar — extraviarse por cuenta propia', 'Descarriarse, errar — extraviarse por cuenta propia: el sentido medio o intransitivo de apartarse de la verdad o del camino recto sin un engañador externo explícito a la vista. La oveja perdida de la parábola «se descarría» (Mateo 18:12), y Jesús dice a los saduceos «estáis en error» (Mateo 22:29; Marcos 12:24, 27). La imaginería de la oveja que se extravía subraya que la responsabilidad recae sobre el propio extraviado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74916, 'spa', 'Error, ilusión, extravío', 'Error, ilusión, extravío. Estado de haberse apartado de la verdad — error, ilusión o creencia falsa, ya sea doctrinal o moral. Es el sentido dominante en el NT, describiendo la condición de quien ha sido extraviado, no el acto de extraviar a otros. Efesios 4:14 advierte contra ''todo viento de doctrina'' y la astucia que produce πλάνη; Santiago 5:20 habla de apartar al pecador del ''error'' de su camino; 2 Tesalonicenses 2:11 presenta la operación de error que Dios permite.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74920, 'spa', 'Engaño, impostura deliberada', 'Engaño, impostura deliberada. Engaño calculado, impostura intencional o fraude — el acto deliberado de inducir a error a otros. En Mateo 27:64 los principales sacerdotes dicen a Pilato que el último ''engaño'' (πλάνη) sería peor que el primero, refiriéndose a una supuesta conspiración de los discípulos. Este sentido marca el paso del error involuntario a la duplicidad premeditada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74921, 'spa', 'Estrellas errantes', 'Las ''estrellas errantes'' de Judas 13, vívida metáfora astronómica para falsos maestros carentes de estabilidad y verdad fija. Los antiguos observaban cómo los planetas vagaban por el cielo, a diferencia de las estrellas fijas. Las traducciones captan esta cualidad errante (''wandering'', ''errantes''), convirtiendo a estos vagabundos celestiales en símbolos de falta de fiabilidad doctrinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74922, 'spa', 'Engañador o impostor', 'Engañador o impostor: quien activamente extravía a otros mediante falsas pretensiones o enseñanzas. El sentido activo del adjetivo («que descarría») predomina en el NT. Los principales sacerdotes califican a Jesús de πλάνος ante Pilato (Mt 27:63), acusación cargada de ironía desde la perspectiva narrativa. Pablo abraza la paradoja en 2 Corintios 6:8 incluyendo «como engañadores, pero veraces» entre las pruebas apostólicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74923, 'spa', 'Tabla de piedra', 'La evidencia multilingue senala superficies planas de escritura. El lexico define πλάξ como «cualquier cosa plana y ancha», incluyendo «piedra plana, tabla» para inscripciones. 2 Co 3:3 contrasta tablas de piedra del antiguo pacto con tablas de corazones de carne. He 9:4 se refiere a las tablas del pacto guardadas en el arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74924, 'spa', 'Objeto moldeado', 'El objeto moldeado que no tiene derecho a cuestionar a su creador en Romanos 9:20. La pregunta retórica de Pablo se apoya en la imagen ancestral del alfarero y las vasijas de barro. La evidencia interlingüística muestra reconocimiento uniforme del proceso de formación (''thing-formed'', ''formado'', ''formation'', ''Gebilde''), subrayando la dependencia entre creador y creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74926, 'spa', 'Palabras fingidas', 'Las palabras fabricadas y engañosas usadas por los falsos maestros en 2 Pedro 2:3. Las glosas multilingües subrayan su naturaleza artificial y engañosa: ''fabricated'' (inglés), ''fingidas'' (español), ''erdichtet'' (alemán, inventado). No son errores honestos sino falsedades deliberadamente elaboradas para explotar a los creyentes con fines de lucro, en marcado contraste con la enseñanza apostólica genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74927, 'spa', 'Calle, plaza pública', 'Calle ancha, vía principal o plaza pública de una ciudad — lugar de visibilidad pública, comercio y vida comunitaria. Derivado del femenino sustantivado de πλατύς (''ancho''), designa las amplias vías y espacios abiertos donde la gente se congrega, ora, come y realiza negocios. En el NT aparece en contextos de exhibición pública (Mt 6:5), silencio profético (Mt 12:19) y proclamación misionera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74930, 'spa', 'Anchura espacial', 'Anchura o amplitud como medida o dimensión espacial. Efesios 3:18 la emplea metafóricamente como una de cuatro dimensiones del amor incomprensible de Cristo. Apocalipsis 20:9 describe la anchura de la tierra sobre la que se extienden ejércitos hostiles, mientras que Apocalipsis 21:16 registra las dimensiones iguales de la ciudad: longitud, anchura y altura, un cubo perfecto que evoca el Lugar Santísimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74931, 'spa', 'Ensanchar y ampliar', 'La evidencia multilingue destaca la idea de expansion. El lexico define el termino como «ensanchar», incluyendo ampliar territorio, dilatar pupilas y estar «aliviado de preocupacion» (LXX). Mt 23:5 se refiere al ensanchamiento literal de filacterias, mientras que 2 Co 6:11-13 usa la imagen metaforica de un corazon que se abre con generosidad y afecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74932, 'spa', 'Camino ancho', 'La puerta ancha y el camino espacioso de Mateo 7:13 que conduce a la destrucción. Jesús emplea una imagen espacial que resuena en todas las culturas; las glosas multilingües lo traducen uniformemente como ''ancho'' (''wide'', ''ancha'', ''large''). La amplitud simboliza facilidad de acceso y popularidad, haciendo este camino atractivo pero mortalmente engañoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74933, 'spa', 'Peinados trenzados elaborados', 'Los peinados elaborados con trenzas desaconsejados en 1 Timoteo 2:9 como inapropiados para el culto cristiano. La preocupación de Pablo no es el cabello en sí, sino la ostentación de estatus implícita en arreglos costosos y laboriosos. La evidencia multilingüe (''braided-hair'', ''trenzados'') identifica la técnica de trenzado. Estos peinados exhibían riqueza y posición, distrayendo del adorno interior que Pablo valora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74934, 'spa', 'Mayor cantidad', 'El mayor número o cantidad; la mayoría, muy grande. Como superlativo de πολύς, denota el extremo máximo de una escala cuantitativa. Mateo 11:20 se refiere a las ciudades donde ocurrió la mayoría de los milagros de Jesús, mientras que Mateo 21:8 y Marcos 4:1 describen multitudes muy numerosas. En 1 Corintios 14:27, Pablo lo usa para fijar un límite superior: «a lo sumo» dos o tres oradores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74935, 'spa', 'Más en cantidad', 'Sentido comparativo nuclear: más en cantidad o número que otra cosa, con un estándar de comparación explícito o implícito. Es el uso por defecto con 32 ocurrencias. ''Si vuestra justicia no supera (πλείων) la de los escribas'' (Mt 5:20); ''más de doce legiones de ángeles'' (Mt 26:53); ''más que todos ellos'' (Lc 21:3, la ofrenda de la viuda). El español ''más que'' lo traduce directamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74937, 'spa', 'Mayor en rango o importancia', 'Mayor en rango, importancia o valor intrínseco: superioridad cualitativa más que exceso cuantitativo. Cuatro ocurrencias, todas en la tradición sinóptica: ''algo mayor que Jonás está aquí'' (Mt 12:41; Lc 11:32); ''algo mayor que Salomón está aquí'' (Mt 12:42; Lc 11:31). Jesús usa πλείων para afirmar que su persona y ministerio superan a las figuras más grandes de la historia de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74938, 'spa', 'Mayor extensión o duración', 'Mayor extensión en tiempo, espacio o grado: ''más lejos'', ''más tiempo'', ''más ampliamente''. Cinco ocurrencias que expresan continuación o propagación más allá de un punto de referencia. El Sanedrín teme que el mensaje apostólico ''se difunda más'' (Hch 4:17); la enseñanza de Pablo se extendió ''más tiempo'' del esperado (Hch 20:9); Pablo pide a Félix no ''detenerlo más'' (Hch 24:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74939, 'spa', 'La mayoría, los más', 'Uso sustantivado con artículo: ''la mayoría'', ''la mayor parte'', ''el mayor número''. Siete ocurrencias donde πλείονες funciona como sustantivo designando la porción mayor de un grupo. Pablo nota que ''la mayoría de los quinientos'' testigos aún viven (1 Co 15:6); ''la mayoría'' de la multitud efesia no sabía por qué se habían reunido (Hch 19:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74940, 'spa', 'Muchos, numerosos', 'Uso en grado positivo donde la morfología comparativa funciona como ''muchos'' o ''mucho'' sin comparación explícita, fenómeno bien atestiguado en el griego koiné. Siete ocurrencias, frecuentemente en Hechos: ''muchas otras palabras'' (Hch 2:40), ''muchos días'' (Hch 13:31), ''después de muchos años'' (Hch 24:17). Aquí πλείων equivale aproximadamente a πολύς.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74948, 'spa', 'Trenzar y tejer', 'La evidencia multilingue indica uniformemente el sentido de tejer o trenzar. El lexico define el termino como «trenzar, entrelazar», con ejemplos de trenzar cabello y torcer cuerdas. Las tres apariciones en el NT (Mt 27:29, Mr 15:17, Jn 19:2) describen a los soldados trenzando una corona de espinas como parte del escarnio contra Jesus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74949, 'spa', 'Aumentar, abundar, exceder', 'Aumentar en número, cantidad o grado; abundar, multiplicarse o desbordarse más allá de una medida previa. Se aplica a realidades abstractas que crecen: el pecado que se multiplica para que la gracia sobreabunde aún más (Ro 5:20), el amor que se acrecienta entre creyentes (1 Ts 3:12; 2 Ts 1:3), la acción de gracias que aumenta para gloria de Dios (2 Co 4:15), y el excedente material (2 Co 8:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74957, 'spa', 'Explotar o defraudar', 'Aprovecharse, explotar o defraudar: obtener ganancia egoísta a costa de otro, ya sea en lo económico, relacional o espiritual. La etimología (πλέον + ἔχω, ''tener más'') revela la raíz codiciosa: ganar a expensas ajenas. Pablo emplea este verbo en dos contextos principales: la explotación espiritual, donde Satanás podría aprovecharse de la comunidad (2 Cor 2:11), y la explotación material, contra la cual se defiende enérgicamente (2 Cor 7:2; 12:17-18) y advierte a los creyentes (1 Tes 4:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74958, 'spa', 'Persona avara', 'Persona codiciosa o avara que se apodera de más de lo que legítimamente le pertenece. Las cuatro apariciones neotestamentarias se encuentran en listas paulinas de vicios. En 1 Corintios 5:10-11, se prohíbe la asociación con avaros; en 6:10, se les excluye del reino de Dios. Efesios 5:5 establece la notable ecuación de que el πλεονέκτης es un idólatra, pues coloca la ganancia material en el lugar de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74959, 'spa', 'Avaricia, codicia', 'Avaricia, codicia. Un deseo insaciable y explotador de más — ya sea riqueza material, poder o ventaja — que trata a los demás como medios para el beneficio propio. Jesús advierte contra ella como una desorientación fundamental de la vida (Lucas 12:15), Pablo la enumera junto a la inmoralidad sexual y la idolatría (Efesios 4:19; 5:3; Colosenses 3:5), y Pedro la identifica como el motivo detrás de la falsa enseñanza (2 Pedro 2:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74963, 'spa', 'Costado del cuerpo', 'El costado del cuerpo humano, la zona lateral del torso junto a las costillas. En el griego clásico, πλευρά podía designar las costillas propiamente o el flanco de un animal, pero en el Nuevo Testamento se refiere exclusivamente al costado de Jesús en los relatos de la Pasión y la Resurrección. Los equivalentes multilingües — español «costado», francés «côté», alemán «Seite» — denotan el costado corporal y no un «lado» abstracto. Juan 19:34 registra la lanzada del soldado, y Juan 20:20-27 presenta al Resucitado mostrando la herida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74964, 'spa', 'Navegar, viajar por mar', 'Navegar o viajar en barco a través del agua. Todas las apariciones neotestamentarias se refieren a viajes literales por mar: los discípulos atrapados en una tormenta en el mar de Galilea (Lucas 8:23) y los trayectos mediterráneos de Pablo rumbo a Roma (Hechos 27:2, 6, 24). El español «navegar», el francés «naviguer» y el alemán «segeln» se corresponden uniformemente con este único sentido marítimo concreto. La palabra aparece en formas participiales, finitas e infinitivas sin alterar su significado fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74970, 'spa', 'El sentido apocalíptico de una plaga enviada divinamente o aflicción catastrófic', 'El sentido apocalíptico de una plaga enviada divinamente o aflicción catastrófica, que domina 13 ocurrencias, todas en Apocalipsis. Son las siete últimas plagas (Ap 15:1,6,8), las plagas de fuego, humo y azufre (Ap 9:18,20), y las plagas amenazadas contra Babilonia (Ap 18:4,8). El español ''plaga/plagas'' evoca directamente el lenguaje de las narrativas de las plagas del Éxodo, señalando la continuidad teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74971, 'spa', 'Un sentido especializado que denota una herida — específicamente una herida mort', 'Un sentido especializado que denota una herida — específicamente una herida mortal, causante de muerte — concentrado en tres ocurrencias sobre la bestia de Apocalipsis 13. La ''herida de muerte'' de la bestia (πληγὴ τοῦ θανάτου, Ap 13:3,12) fue sanada, causando que el mundo se maravillara. Apocalipsis 13:14 describe además a la bestia ''que tenía la herida de espada y vivió.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74973, 'spa', 'El sentido físico concreto de un golpe, azote o llaga infligida por violencia hu', 'El sentido físico concreto de un golpe, azote o llaga infligida por violencia humana. Lucas 10:30 describe al hombre que ''cayó en manos de ladrones'' y recibió golpes (πληγάς). Pablo cataloga sus propios sufrimientos incluyendo ''azotes'' (2 Co 6:5, 11:23), y el carcelero de Filipos lavó las ''llagas'' de Pablo y Silas (Hch 16:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74978, 'spa', 'Multitud, muchedumbre — un gran grupo de personas reunidas, una muchedumbre, tur', 'Multitud, muchedumbre — un gran grupo de personas reunidas, una muchedumbre, turba o asamblea. Este sentido abrumadoramente dominante (30 veces) aparece a lo largo de Lucas-Hechos y Marcos, describiendo discípulos, adoradores y reuniones públicas. La hueste celestial de Lucas 2:13 y la multitud de adoradores en el templo de Lucas 1:10 ilustran el amplio rango de aplicación a grupos de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74981, 'spa', 'Cantidad, gran número de cosas — una gran cantidad o volumen de cosas no humanas', 'Cantidad, gran número de cosas — una gran cantidad o volumen de cosas no humanas. Este sentido raro (1 vez) aparece en Hechos 28:3, donde Pablo recoge una cantidad de ramas secas para hacer fuego en Malta. El español distingue este sentido con «cantidad» en vez de «multitud», revelando que los traductores marcan instintivamente el cambio de personas a objetos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74983, 'spa', 'Ser multiplicado, crecer o aumentar en número, usado de forma intransitiva o en ', 'Ser multiplicado, crecer o aumentar en número, usado de forma intransitiva o en voz pasiva. Describe el crecimiento orgánico de la iglesia primitiva (Hch 6:7; 9:31; 12:24), la multiplicación del pueblo de Israel en Egipto (Hch 7:17), el aumento de la iniquidad en los últimos días (Mt 24:12) y el deseo epistolar de que la gracia y la paz abunden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74988, 'spa', 'Multiplicar o aumentar algo, usado de forma transitiva con Dios o una persona co', 'Multiplicar o aumentar algo, usado de forma transitiva con Dios o una persona como agente activo que causa el crecimiento. Dios promete multiplicar la descendencia de Abraham (He 6:14, citando Gn 22:17) y Pablo pide a Dios que multiplique la semilla de los corintios para la siembra (2 Co 9:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74992, 'spa', 'Llenar o ser llenado con una sustancia física, una emoción o especialmente el Es', 'Llenar o ser llenado con una sustancia física, una emoción o especialmente el Espíritu Santo, resultando en un estado de plenitud que impulsa el hablar o el actuar. Lucas 1:15 promete que Juan el Bautista será lleno del Espíritu Santo desde el vientre; Elisabet (Luc 1:41) y Zacarías (Luc 1:67) son llenos y profetizan. Las bodas de Caná y Pentecostés (Hch 2:4) extienden este sentido tanto al ámbito físico como al espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74993, 'spa', 'Llevar un período de tiempo, una profecía o un acontecimiento señalado a su cump', 'Llevar un período de tiempo, una profecía o un acontecimiento señalado a su cumplimiento o consumación, indicando que el plazo designado ha llegado a su término. Lucas 1:23 señala que los días del servicio sacerdotal de Zacarías ''se cumplieron''; Lucas 1:57 que el tiempo de dar a luz de Elisabet ''se cumplió''. El español ''cumplirse'' distingue claramente este sentido del de llenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75003, 'spa', 'Inundación probatoria', 'La inundación que azota la casa en la parábola de Jesús en Lucas 6:48, poniendo a prueba qué cimiento resulta fiable. Los constructores mediterráneos conocían el peligro de las crecidas estacionales. Las glosas multilingües reconocen uniformemente la embestida destructiva (''a-flood'', ''inundación'', ''inondation''). La riada es metáfora de las pruebas inevitables que exponen la fe superficial frente a la arraigada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75004, 'spa', 'Pero, sin embargo — conjunción adversativa que marca contraste, concesión o mati', 'Pero, sin embargo — conjunción adversativa que marca contraste, concesión o matización: «pero», «sin embargo», «no obstante». Es el uso dominante (23 veces), que con frecuencia hace pivotar de un pensamiento a su contrapunto. La oración de Jesús en Getsemaní, «sin embargo, no como yo quiero» (Mateo 26:39), y los ayes (Mateo 11:22, 24; 18:7) ejemplifican la fuerza concesiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75006, 'spa', 'Excepto, solo, aparte de — partícula preposicional o limitativa que significa «e', 'Excepto, solo, aparte de — partícula preposicional o limitativa que significa «excepto», «solo» o «aparte de», restringiendo o excluyendo de una categoría más amplia. «Nadie quedó excepto la mujer» (Juan 8:10); la iglesia de Jerusalén fue dispersada «excepto los apóstoles» (Hechos 8:1); el Espíritu Santo testifica en cada ciudad «sino que» le esperan prisiones (Hechos 20:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75013, 'spa', 'Lleno, colmado, repleto', 'Lleno, colmado, repleto: el sentido primario y casi universal que abarca tanto la plenitud física como la espiritual. Físicamente, las canastas están ''llenas'' de pedazos (Mt 14:20, 15:37, Mr 8:19-20), una espiga está ''llena'' (Mr 4:28) y una esponja está ''llena de vinagre''. Espiritualmente, se describe a personas como ''llenas del'' Espíritu Santo (Lc 4:1, Hch 7:55), de gracia y verdad (Jn 1:14), de fe y poder (Hch 6:5, 8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75014, 'spa', 'Lleno en el sentido de ''completo, medida plena'', específicamente en 2 Jn 1', 'Lleno en el sentido de ''completo, medida plena'', específicamente en 2 Jn 1:8, donde el autor escribe ''para que recibáis galardón completo''. Aquí el énfasis no recae en un recipiente que se llena, sino en el carácter completo o íntegro de lo que se recibe. El español traduce con ''plena'' (en lugar del habitual ''lleno/llena''), marcando sutilmente el paso de la plenitud espacial a la completitud abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75015, 'spa', 'Plena convicción', 'Estar plenamente convencido, completamente persuadido o del todo seguro acerca de algo. Abraham estaba πληροφορηθείς de que Dios era capaz de cumplir su promesa (Rom 4:21); cada persona debe estar πληροφορείσθω en su propia mente respecto a la observancia de días (Rom 14:5); y Pablo ora para que los colosenses permanezcan πληροφορημένοι en la voluntad de Dios (Col 4:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75017, 'spa', 'Cumplir plenamente', 'Cumplir, llevar a plena realización o consumar por entero. Lc 1:1 habla de sucesos πεπληροφορημένων («plenamente cumplidos») entre los primeros creyentes. Pablo exhorta a Timoteo a que πληροφόρησον su ministerio, es decir, que lo lleve a cabo cabalmente (2 Ti 4:5), e informa que por medio de él el mensaje fue πληροφορηθῇ, proclamado en plenitud (2 Ti 4:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75021, 'spa', 'Plena certeza', 'Plena certeza o convicción completa, especialmente en asuntos de fe y esperanza. Colosenses 2:2 habla de las riquezas de plena certeza que vienen del entendimiento del misterio de Dios. En 1 Tesalonicenses 1:5, la πληροφορία acompaña al poder del Espíritu en la recepción del evangelio. Hebreos 6:11 y 10:22 instan a los creyentes a mantener esta plena certeza en la esperanza y la fe, acercándose a Dios con un corazón sincero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75022, 'spa', 'cumplir profecía (pasivo)', 'Cumplir profecía o Escritura en voz pasiva: el sentido dominante con 38 ocurrencias, concentrado en Mateo y Juan. La fórmula característica ἵνα πληρωθῇ (''para que se cumpliese'') aparece 16 veces solo en Mateo, organizando estructuralmente el Evangelio como un relato de consumación profética. El árabe tamm/yatimm y el coreano 이루어지다 confirman este eje de completitud divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75024, 'spa', 'ser lleno (pasivo/medio)', 'Ser lleno de contenido espiritual o emocional en voz pasiva o media: 16 ocurrencias donde personas o lugares se colman del Espíritu Santo, gozo, tristeza o conocimiento. Los discípulos ''fueron llenos de gozo y del Espíritu Santo'' (Hch 13:52), Jesús dice que ''la tristeza ha llenado vuestro corazón'' (Jn 16:6), y Pablo ora para que los creyentes ''sean llenos de toda la plenitud de Dios'' (Ef 3:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75025, 'spa', 'cumplir activamente', 'Cumplir activamente: llevar a cabo, completar o ejecutar un deber, ley o misión en voz activa con agente humano (14 ocurrencias). Jesús declara que vino ''no a abolir la Ley sino a cumplirla'' (Mat 5:17); Pablo afirma que el amor es ''el cumplimiento de la ley'' (Ro 13:8). En Mat 3:15, Jesús le dice a Juan el Bautista que conviene ''cumplir toda justicia''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75026, 'spa', 'completar un período', 'Completar un período, curso o tiempo señalado: 10 ocurrencias donde un lapso temporal alcanza su fin establecido. ''Los tiempos de los gentiles se cumplan'' (Lc 21:24); ''hasta que las palabras de Dios se cumplan'' (Ap 17:17). El árabe akmala (''completar'') y el coreano 마치다 (''terminar'') confirman el matiz de conclusión temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75028, 'spa', 'llenar espacialmente (activo)', 'Llenar espacialmente en voz activa: colmar un espacio, recipiente o lugar con sustancia tangible (10 ocurrencias). Todo valle ''será llenado'' (Lc 3:5 citando a Isaías), la casa ''se llenó'' de la fragancia del perfume (Jn 12:3), ''un estruendo llenó toda la casa'' en Pentecostés (Hch 2:2), y Ananías ''llenó'' su corazón con el engaño de Satanás (Hch 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75074, 'spa', 'Plenitud o totalidad de la presencia, el poder o la bendición divina', 'Plenitud o totalidad de la presencia, el poder o la bendición divina. Jn 1:16 habla de recibir de la plenitud de Cristo, mientras que Col 1:19 y 2:9 declaran que la plenitud de Dios habita en el Hijo. Pablo también usa πλήρωμα para la consumación escatológica: la ''plenitud de los gentiles'' (Ro 11:25) y el ''cumplimiento del tiempo'' (Gá 4:4, Ef 1:10). Este es el sentido teológicamente más denso del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75075, 'spa', 'Lo que llena un recipiente o un espacio', 'Lo que llena un recipiente o un espacio: el contenido físico o complemento. Tras los milagros de alimentación, los discípulos recogieron doce canastas ''llenas'' de pedazos (Mr 6:43; 8:20). En Mt 9:16 y Mr 2:21, la tela sin encoger como ''remiendo'' se desgarra del vestido llevándose consigo su plenitud. Aquí la palabra conserva su concreción del griego clásico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75077, 'spa', 'Cumplimiento o satisfacción completa de un requisito, especialmente la ley mosai', 'Cumplimiento o satisfacción completa de un requisito, especialmente la ley mosaica. En Ro 13:10 Pablo declara que el amor es el πλήρωμα de la ley: no su abolición, sino su realización plena. El español ''cumplimiento'' distingue claramente este sentido del abstracto ''plenitud'', destacando la consumación activa de una obligación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75079, 'spa', 'El prójimo en sentido ético y relacional -- un ser humano hacia quien se tienen ', 'El prójimo en sentido ético y relacional -- un ser humano hacia quien se tienen deberes morales, especialmente la obligación de amar (16 ocurrencias). Este uso sustantivado domina el NT, anclado en el doble mandamiento del amor (Mt 22:39; Mr 12:31) y la parábola del buen samaritano (Lc 10:27-29). El español prójimo y el francés prochain derivan de palabras que significan ''cerca,'' preservando el paso de la proximidad física al deber ético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75080, 'spa', 'Proximidad espacial -- ''cerca'' o ''próximo a'' un lugar', 'Proximidad espacial -- ''cerca'' o ''próximo a'' un lugar. La única aparición de este sentido locativo en el NT es Juan 4:5, donde la ciudad samaritana de Sicar se describe como cercana al terreno que Jacob dio a José. El español cerca y el inglés near reflejan el significado espacial directo. Este uso preserva el sentido clásico griego y recuerda al lector que el ''prójimo'' ético nació de una simple palabra de cercanía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75081, 'spa', 'Indulgencia carnal', 'La indulgencia de la carne que las reglas ascéticas no logran contener en Colosenses 2:23. El argumento de Pablo es contraintuitivo: la disciplina corporal severa no vence los deseos carnales, simplemente los desvía. El término abarca tanto la saciedad física como la gratificación de apetitos. Las traducciones multilingües varían (''indulgence'', ''satisfacción'', ''Saettigung''), reflejando su rango semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75082, 'spa', 'Golpe cósmico apocalíptico', 'El golpe que hiere los cuerpos celestes en Apocalipsis 8:12 durante el juicio apocalíptico. Una tercera parte del sol, la luna y las estrellas son heridas, reduciendo su luz. Las traducciones multilingües reflejan un entendimiento constante de golpe contundente (''was-struck'', ''fue-herida'', ''frapper''). Este golpe cósmico demuestra el poder divino sobre la creación, evocando la plaga egipcia de tinieblas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75083, 'spa', 'Barquita o bote', 'Embarcación pequeña o bote: forma diminutiva de πλοῖον (barco/nave), que indica un navío de tamaño modesto apto para actividad costera en un lago. El sufijo diminutivo -αριον expresa pequeñez, distinguiéndolo del πλοῖον más grande usado para travesías en aguas abiertas. En Marcos 3:9, Jesús solicita una barquita como refugio flotante ante la presión de la multitud. En Juan 6:22-24, la barquita funciona como detalle narrativo del milagro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75084, 'spa', 'barca pequeña (escindido)', 'Barca pequeña o embarcación de pesca en aguas interiores, sentido escindido del anterior para distinguir usos evangélicos específicos. Se refiere a la modesta embarcación de remos de los discípulos en el mar de Galilea, desde la cual pescan, Jesús enseña y que las tormentas sacuden en los relatos sinópticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75085, 'spa', 'navío de travesía', 'Navío mayor de altura usado para travesías marítimas mediterráneas, concentrado en Hechos y Apocalipsis. Pablo embarca en un πλοῖον en Troas (Hch 20:13), navega a Fenicia (Hch 21:2-3) y naufraga en un carguero alejandrino (Hch 27:1-44). Los mercaderes de Apocalipsis lloran sobre los navíos ardientes (Ap 18:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75089, 'spa', 'Travesía marítima', 'Las glosas multilingües apuntan uniformemente al viaje por mar: español «navegación/viaje», francés «navigation», alemán conserva las formas griegas πλοός/πλοῦν. El léxico lo define como «navegación, viaje marítimo», incluyendo el sentido de «temporada propicia para navegar». Hechos 21:7 describe la conclusión de un viaje y la llegada a puerto. Hechos 27:9-10 advierte que la travesía se ha vuelto peligrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75090, 'spa', 'Acaudalado, que posee abundantes recursos materiales; usado tanto como adjetivo ', 'Acaudalado, que posee abundantes recursos materiales; usado tanto como adjetivo descriptivo como sustantivo (''un hombre rico''). La enseñanza de Jesús sobre el rico y el ojo de la aguja (Mat 19:23-24; Mar 10:25) y la parábola del hombre rico y Lázaro (Luc 16:19-22) hacen de este un término cargado teológicamente. Pablo lo aplica metafóricamente a Dios, quien es ''rico en misericordia'' (Ef 2:4), extendiendo el campo semántico más allá de lo económico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75093, 'spa', 'Ricamente, con abundancia', 'De manera rica, abundante y desbordante. En el Nuevo Testamento se usa exclusivamente para la generosidad divina o espiritual: la palabra que mora en el creyente (Col 3:16), la provisión de Dios para nuestro disfrute (1 Tim 6:17), el derramamiento del Espíritu (Tit 3:6) y la entrada generosa al reino de Cristo (2 Pe 1:11). Transmite un desbordamiento que va mucho más allá de lo meramente suficiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75094, 'spa', 'Hacerse rico en posesiones materiales o prosperidad económica', 'Hacerse rico en posesiones materiales o prosperidad económica. Usado de los mercaderes enriquecidos por el comercio de Babilonia (Ap 18:3, 15, 19), del rico autoengañado (Lc 12:21) y de la confianza mal puesta de la iglesia de Laodicea en la riqueza (Ap 3:17). Lc 1:53 invierte la expectativa: Dios despide a los ricos con las manos vacías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75095, 'spa', 'Ser enriquecido espiritualmente, por la gracia de Dios o su don salvífico', 'Ser enriquecido espiritualmente, por la gracia de Dios o su don salvífico. Pablo emplea este sentido con fuerza: los creyentes son enriquecidos mediante la pobreza voluntaria de Cristo (2 Co 8:9), y los corintios se jactan de haber ''llegado a ser ricos'' en dones espirituales (1 Co 4:8, con suave ironía). Dios es ''rico para con todos los que le invocan'' (Ro 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75103, 'spa', 'Enriquecer', 'La evidencia multilingüe subraya el sentido de hacer rico: español «enriqueciendo/fuisteis enriquecidos», francés «enrichir», alemán «reich machen». El léxico lo define como «hacer rico, enriquecer». En 1 Co 1:5 se describe el ser enriquecido en palabra y conocimiento en Cristo. En 2 Co 6:10 se presenta la paradoja de ser pobre y a la vez enriquecer a muchos. En 2 Co 9:11 el enriquecimiento impulsa la generosidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75104, 'spa', 'Riqueza y abundancia, usada concretamente para la prosperidad material (Mat 13', 'Riqueza y abundancia, usada concretamente para la prosperidad material (Mat 13:22; Mar 4:19, donde las riquezas ahogan la palabra) y metafóricamente para la plenitud divina (Rom 9:23, ''riquezas de gloria''; Ef 3:8, ''las inescrutables riquezas de Cristo''). La extensión metafórica es característicamente paulina. El español ''riqueza/riquezas'' cubre ambos registros sin distinción léxica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75106, 'spa', 'Lavar telas', 'Las glosas multilingües indican uniformemente la acción de lavar: español «lavaban/lavando/lavaron», francés «laver», alemán «waschen». El léxico lo define como «lavar, limpiar, propiamente ropa, lienzos, etc.», en contraste con λούομαι («bañarse») y νίζω («lavarse las manos»). Lucas 5:2 describe a pescadores lavando redes. Apocalipsis 7:14 y 22:14 hablan de lavar vestiduras en la sangre del Cordero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75107, 'spa', 'Espíritu Santo / Espíritu de Dios', 'Variante clasificatoria del sentido dominante: el Espíritu Santo, Espíritu de Dios o de Cristo, en apariciones donde la formulación contextual difiere levemente del sentido 1 pero el referente es idéntico. Cubre contextos trinitarios, fórmulas bautismales (Mt 28:19) y la obra del Espíritu en la inspiración escrituraria. El español emplea uniformemente ''Espíritu'' con mayúscula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75111, 'spa', 'espíritu humano / disposición interior', 'El espíritu humano como disposición o actitud interior — cinco apariciones donde πνεῦμα designa la vida anímica más que la divina. Lucas 1:80 (''el niño se fortalecía en espíritu''), Romanos 8:13 (''por el Espíritu/espíritu, hacéis morir las obras del cuerpo'') y los pasajes notoriamente ambiguos de 1 Pedro 3:18 y 4:6 muestran la línea difusa entre lo humano y lo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75112, 'spa', 'ser espiritual / entidad sobrenatural', 'Un ser espiritual o entidad sobrenatural más amplio que el sentido demoníaco estricto. Seis apariciones incluyen los ''espíritus'' como manifestaciones espirituales en las asambleas (1 Co 14:12) y los ''siete espíritus'' ante el trono (Ap 3:1; 5:6). El coreano 영들 (espíritus, plural) y el suajili roho distinguen este uso del Espíritu Santo singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75116, 'spa', 'viento', 'Viento físico o aire en movimiento — una sola aparición clara en Juan 3:8, donde Jesús dice: ''el viento (τὸ πνεῦμα) sopla de donde quiere''. El griego explota deliberadamente el doble sentido: la misma palabra designa el fenómeno natural y el Espíritu divino en el mismo versículo. El español emplea ''viento'' aquí, distinguiéndolo netamente de ''espíritu''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75118, 'spa', 'aliento, soplo vital', 'Aliento o soplo vital — una sola aparición en 2 Tesalonicenses 2:8, donde el Señor Jesús destruirá al inicuo ''con el soplo (πνεύματι) de su boca''. Evoca Isaías 11:4 (hebreo רוּחַ) y pone en primer plano la metáfora física del aliento exhalado como instrumento de poder divino. El español emplea ''soplo'' o ''aliento'', distinguiéndolo del vocabulario espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75119, 'spa', 'Perteneciente a o caracterizado por el Espíritu divino; espiritual en naturaleza', 'Perteneciente a o caracterizado por el Espíritu divino; espiritual en naturaleza, origen o cualidad. Usado adjetivalmente para describir personas, realidades o cualidades formadas por el πνεῦμα de Dios en contraste con la carne. Pablo llama a la ley ''espiritual'' (Rom 7:14), contrasta a la persona espiritual con la natural (1 Co 2:15; 3:1) y habla de bendiciones espirituales (Ef 1:3). La uniformidad de traducción entre lenguas confirma un núcleo semántico estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75121, 'spa', 'Cosas, dones o asuntos espirituales — el adjetivo usado como sustantivo (τὰ πνευ', 'Cosas, dones o asuntos espirituales — el adjetivo usado como sustantivo (τὰ πνευματικά). Pablo emplea esta forma especialmente al tratar los dones carismáticos: ''acerca de los dones espirituales'' (1 Co 12:1; 14:1). En Rom 15:27 y 1 Co 9:11 contrasta las ''cosas espirituales'' sembradas con las ''cosas materiales'' cosechadas, estableciendo una economía entre ambos órdenes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75126, 'spa', 'Soplar (del viento)', 'Soplar, referido al viento o al aire en movimiento — describe el fenómeno natural del viento soplando, aplicado tanto a relatos de tormenta como a metáforas teológicas. En Mateo 7:25 y 7:27 vientos destructores «soplan» contra las casas en la parábola de Jesús. En Juan 3:8 el verbo adquiere un rico doble sentido: el viento «sopla donde quiere», en paralelo con el movimiento soberano e invisible del Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75131, 'spa', 'Ahogar o sofocar', 'La evidencia multilingüe subraya la sofocación: español «ahogaron/ahogaba/ahogaban», francés «étouffer», alemán conserva las formas griegas ἐπνίγοντο/ἔπνιγεν/ἔπνιξαν. El léxico lo define como «ahogar, estrangular, sofocar», con sentido pasivo «ser ahogado, asfixiado». Mateo 13:7 describe espinos que ahogan las plantas. Mateo 18:28 muestra a un hombre estrangulando a su deudor. Marcos 5:13 narra cerdos ahogándose en el mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75132, 'spa', 'Carne estrangulada', 'Las glosas multilingües apuntan consistentemente a la carne estrangulada: español «ahogado/estrangulado», francés «asphyxié», alemán conserva las formas griegas πνικτοῦ/πνικτόν/πνικτῶν. El léxico lo define como «estrangulado» (de πνίγω «ahogar»), referido a carne, y señala un sentido secundario de «hermético» o «guisado». Los tres usos neotestamentarios (Hch 15:20, 29; 21:25) se refieren a carne no desangrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75134, 'spa', 'Túnica talar sacerdotal', 'La vestidura talar que viste el Cristo glorificado en Apocalipsis 1:13, marcando su dignidad sacerdotal y real. El sumo sacerdote del Antiguo Testamento vestía una prenda semejante (Éxodo 28:4), detalle sumamente significativo. Las traducciones multilingües reconocen su longitud (''foot-length-robe'', ''con-túnica-hasta-los-pies''), comunicando visualmente el papel exaltado de Cristo como mediador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75135, 'spa', 'Adverbio interrogativo que pregunta ''¿de dónde?'' en términos de lugar, origen o ', 'Adverbio interrogativo que pregunta ''¿de dónde?'' en términos de lugar, origen o causa, frecuentemente con matices de asombro o misterio teológico. En Nazaret, expresa la incredulidad de la multitud ante la autoridad de Jesús (Mat 13:27, 54, 56). En Caná, el maestresala no sabe ''de dónde'' vino el vino (Juan 2:9). Pilato pregunta a Jesús ''¿De dónde eres tú?'' (Juan 19:9), elevando una pregunta espacial a un nivel cristológico profundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75137, 'spa', 'hacer, actuar, realizar', 'El sentido fundamental de ejecutar cualquier acción o actividad — el ''hacer'' general que aparece 473 veces. Cuando Jesús pregunta ''¿Qué queréis que os haga?'' (Mt 9:28) o los fariseos cuestionan ''¿Por qué hacéis lo que no es lícito?'' (Mt 12:2), domina este sentido básico. Es el valor por defecto para la acción inespecífica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75153, 'spa', 'hacer, construir, crear', 'Fabricar, construir o dar existencia material a algo — el ''hacer'' concreto que aparece 62 veces. Juan el Bautista cita a Isaías: ''Enderezad sus sendas'' (Mt 3:3). Jesús enseña que no podemos ''hacer un cabello blanco o negro'' (Mt 5:36). El sentido abarca tanto la fabricación física como la preparación metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75168, 'spa', 'producir, dar fruto', 'Producción agrícola y metafórica de fruto o resultados — lo que brota naturalmente de la propia naturaleza. Con 15 apariciones: Juan advierte que ''todo árbol que no produce buen fruto es cortado'' (Mt 3:10), y Jesús enseña que el buen árbol ''produce buenos frutos'' (Mt 7:17-19). El sentido vincula carácter interior con resultado visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75181, 'spa', 'pasar tiempo', 'Transcurrir o permanecer durante un período de tiempo en un lugar o actividad — duración temporal más que acción. Cuatro apariciones: Pablo escribe ''pasé tres meses'' en Grecia (Hch 20:3) y ''una noche y un día he estado en lo profundo'' (2 Co 11:25). El foco está en el transcurso del tiempo, no en las actividades que lo llenaron.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75190, 'spa', 'causar, convertir en', 'El sentido causativo de hacer que alguien o algo llegue a ser de cierta manera — provocar un efecto. Ocho apariciones: Jesús ''constituyó doce'' apóstoles (Mc 3:14-16), designándolos para un nuevo estado. El sentido implica transformación o conferimiento de un estatus nuevo, ya sea social o espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75206, 'spa', 'cometer, perpetrar', 'Cometer o perpetrar un acto indebido — realizar una acción negativa. Dos pasajes usan este sentido: Marcos describe a los sediciosos que ''habían cometido homicidio'' (Mc 15:7), y Pablo pregunta retóricamente ''¿Cometí pecado?'' (2 Co 11:7). El verbo es neutro, pero el contexto especifica la acción como transgresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75209, 'spa', 'celebrar, observar', 'Observar, celebrar o guardar una fiesta o práctica religiosa — cumplimiento ritual. Tres apariciones: Jesús dice a los discípulos ''celebraré la Pascua en tu casa'' (Mt 26:18), y Hebreos señala que Moisés ''celebró la Pascua'' (He 11:28). El sentido se aplica específicamente a la observancia de festividades sagradas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75210, 'spa', 'considerar, estimar', 'Considerar o estimar algo de cierta manera — evaluación cognitiva más que acción física. Dos apariciones: Pablo escribe ''no estimo mi vida como preciosa'' (Hch 20:24). La operación mental más que física distingue este sentido, donde ''hacer'' se desliza hacia ''juzgar'' o ''tener por''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75218, 'spa', 'hacer (narrativo)', 'Sentido incierto con una sola aparición en Hechos 1:1, donde Lucas se refiere a su libro anterior sobre ''todas las cosas que Jesús comenzó a hacer y a enseñar''. Las tradiciones de traducción difieren en si se trata de simple narración o de referencia a los hechos de Jesús. El contexto metaliterario dificulta la clasificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75223, 'spa', 'constituir, designar', 'Otra aparición única que describe a Moisés como aquel que ''fue constituido'' o ''hecho fiel'' (He 3:2). La voz pasiva o media y el contexto singular (Dios designando a Moisés en su oficio) pueden justificar un sentido distinto de nombramiento divino, aunque podría subsumirse bajo el sentido causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75233, 'spa', 'trabajar, laborar', 'Trabajar o esforzarse en una tarea — labor ocupacional. Dos apariciones: en la parábola de la viña, los obreros se quejan de que ''estos últimos trabajaron una hora'' (Mt 20:12). El sentido enfatiza el esfuerzo sostenido o la labor deliberada hacia una meta, con connotaciones de fatiga o empeño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75262, 'spa', 'Práctica activa', 'La práctica concreta que Santiago 1:25 celebra: bienaventurado el hacedor de la palabra, no solo el oyente. El término enfatiza la ejecución y el cumplimiento. Las traducciones multilingües (''doing'', ''hacer'', ''Tun'') captan esta dimensión activa. Santiago contrasta la futilidad de oír sin hacer con la bendición de quienes practican la ley perfecta de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75263, 'spa', 'Hacedor, ejecutor', 'Hacedor, aquel que actúa conforme a algo o lo lleva a cabo, especialmente la ley o la palabra de Dios. Santiago emplea este término con énfasis: los creyentes deben ser ποιηταὶ λόγου, hacedores de la palabra (Stg 1:22-25), no meros oyentes. Pablo argumenta de modo similar en Rom 2:13 que los «hacedores de la ley» serán justificados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75265, 'spa', 'Poeta, compositor', 'Poeta o compositor literario, aquel que crea versos. En Hch 17:28, Pablo cita a poetas griegos paganos en el Areópago: «como algunos de vuestros propios ποιηταί han dicho, porque somos también linaje suyo». Este es el significado original del griego clásico: el «hacedor» por excelencia era el poeta que daba forma al lenguaje como arte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75266, 'spa', 'Diverso, variado', 'Diverso, variado. De muchas clases, variado en forma o carácter — aplicado tanto a realidades negativas (diversas enfermedades, Mateo 4:24; Marcos 1:34; diversas tentaciones, Santiago 1:2; 2 Timoteo 3:6) como a la acción positiva de Dios (gracia multiforme, 1 Pedro 4:10; diversos milagros, Hebreos 2:4). La palabra no especifica en qué consiste la variedad; simplemente señala una rica multiplicidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75269, 'spa', 'Pastorear/gobernar (espiritual y mesiánico)', 'Pastorear/gobernar (espiritual y mesiánico). Pastoreo espiritual o mesiánico: guiar, gobernar o ejercer cuidado pastoral sobre personas bajo autoridad divina. Cristo es profetizado como quien ''pastoreará a mi pueblo Israel'' (Mateo 2:6), y encomienda lo mismo a Pedro (Juan 21:16). En Apocalipsis, este sentido se intensifica hasta el gobierno soberano: pastorear las naciones con vara de hierro (Apocalipsis 2:27; 12:5; 19:15). Pablo exhorta a los ancianos de Éfeso a ''pastorear la iglesia del Señor'' (Hechos 20:28).');